import {createSignal, isHydrating, onSettled, type Accessor} from 'solid-js';
import {isServer, type JSX} from '@solidjs/web';
import {useId} from '../utils/useId';

export interface SSRProviderProps {
  /** Your application here. */
  children: JSX.Element;
}

// Native unique IDs already have request/root ownership, as in the modern source branch.
export function SSRProvider(props: SSRProviderProps): JSX.Element {
  return props.children;
}

/** @private */
export const useSSRSafeId = useId;

/** True during server rendering and the initial hydration pass. */
export function useIsSSR(): Accessor<boolean> {
  const [isSSR, setIsSSR] = createSignal(isServer || isHydrating());
  // Reserve the same lifecycle slot on server and client.
  onSettled(() => { setIsSSR(false); });
  return isSSR;
}
